solutionCode:
function setupClickOutside(refNode, onOutsideClick) {
  function handler(event) {
    if (!refNode || !refNode.contains) return;
    if (!refNode.contains(event.target)) {
      onOutsideClick(event);
    }
  }

  return handler;
}
